14	// 本文件锁定“归档读取”侧的字符合法性拒绝，与 audit 提交侧
15	// (jsonchars_test.go) 完全对齐。audit 提交早已拒绝非法字符，但读取已保存
16	// 报告时 json.Unmarshal 会静默把两类非法输入改写成 U+FFFD：
17	//   - JSON 字符串里的非法 UTF-8 字节；
18	//   - 未配对的高/低代理项、低代理项在前的错误配对顺序。
19	//
20	// 于是一份说明与证据都合法地含有 U+FFFD 的报告，把这两处换成孤立代理转义
21	// 后，解码内容与原报告逐字节相同——重算 reportId 一致、证据与说明也一致，
22	// 整份损坏归档就会被当成原报告读出。读取成功必须表示归档本身合法：任何成员
23	// 名称或字符串值（含成员名、规则说明、缺陷证据及未知扩展成员的嵌套对象和
24	// 数组，扩展成员不参与报告标识也不放行）出现字符问题，都必须把整份报告判为
25	// 归档损坏，即使改写后能算出相同 reportId。损坏归档原字节保留，不修复、替换
26	// 或删除；diff 任一侧损坏则整次比较失败；audit 遇到同标识既有损坏归档不能
27	// 视为保存成功。合法中文、前后空格、换行、正确成对的代理转义、直接书写的同
28	// 一字符、原文中的 U+FFFD 与“转义反斜线后接 uD800”文本继续正常读取。
29	
30	// replacementCharBytes 是直接书写的 U+FFFD 的 UTF-8 编码。
31	var replacementCharBytes = []byte{0xEF, 0xBF, 0xBD}
32	
33	// oneRuleCharReport 构造一份只有一条“发现缺陷”规则的合法报告，其说明与证据
34	// 都是 note（二者必须一致），用于按文本方式注入字符问题。
35	func oneRuleCharReport(note string) Report {
36		hash := ArtifactHash(sampleArtifact())
37		return Report{
38			Artifact: ReportArtifact{Name: "Vault", Hash: hash},
39			Rules: []ReportRule{
40				{ID: "r1", Kind: "static", Severity: "high", Invariant: "inv", Version: "1", Status: StatusDefect, Note: note},
41			},
42			Findings: []ReportFinding{
43				{ArtifactHash: hash, RuleID: "r1", Version: "1", Severity: "high", Invariant: "inv", Evidence: note},
44			},
45		}
46	}
47	
48	// expectCorruptCharLoad 断言字符损坏归档的完整读取契约：errCorrupt 且点名
49	// 请求的报告标识与所有要求的定位片段，返回零值报告，归档原字节保留。
50	func expectCorruptCharLoad(t *testing.T, dir, id string, data []byte, wantSubstrings ...string) {
51		t.Helper()
52		path := filepath.Join(dir, id+".json")
53		got, err := LoadReport(dir, id)
54		if err == nil {
55			t.Fatalf("character-illegal archive must be rejected, got %+v", got)
56		}
57		var ec errCorrupt
58		if !errors.As(err, &ec) {
59			t.Fatalf("character problems classify as errCorrupt, got %T: %v", err, err)
60		}
61		msg := err.Error()
62		if !strings.Contains(msg, id) {
63			t.Fatalf("error must name the requested report id %q: %v", id, err)
64		}
65		if !strings.Contains(msg, "archive is corrupt") {
66			t.Fatalf("error must classify the archive as corrupt: %v", err)
67		}
68		for _, want := range wantSubstrings {
69			if !strings.Contains(msg, want) {
70				t.Fatalf("error %q must contain %q", msg, want)
71			}
72		}
73		if !reflect.DeepEqual(got, Report{}) {
74			t.Fatalf("failed read must return the zero report, got %+v", got)
75		}
76		after, err := os.ReadFile(path)
77		if err != nil {
78			t.Fatalf("corrupt archive must not be deleted: %v", err)
79		}
80		if string(after) != string(data) {
81			t.Fatal("failed read must not rewrite, repair or replace the archive bytes")
82		}
83	}
84	
85	// --- 核心场景：说明与证据的合法 U+FFFD 都换成孤立高代理项，仍必须拒绝 ---
86	
87	func TestLoadReportLoneSurrogateLaunderingRejected(t *testing.T) {
88		dir := t.TempDir()
89		r := oneRuleCharReport("反例：�重入")
90		legalID := ReportID(r)
91	
92		// 说明与证据两处的直接 U+FFFD 都换成 \uD800：解码器会把它们各自改写回
93		// U+FFFD，所以除字符关外没有任何一关能拒绝这份归档。
94		id := writeVariantArchiveText(t, dir, r, func(doc string) string {
95			return strings.ReplaceAll(doc, string(replacementCharBytes), `\uD800`)
96		})
97		if id != legalID {
98			t.Fatalf("the rewritten content computes the same report id, got %s want %s", id, legalID)
99		}
100		data, err := os.ReadFile(filepath.Join(dir, id+".json"))
101		if err != nil {
102			t.Fatal(err)
103		}
104		// 偏移必须正好指向原始文件中说明处逃逸的反斜线。
105		wantOffset := strings.Index(string(data), `"note":"反例：\uD800`)
106		if wantOffset < 0 {
107			t.Fatal("test setup: mutated note not found in archive")
108		}
109		escapeOffset := wantOffset + len(`"note":"反例：`)
110		expectCorruptCharLoad(t, dir, id, data,
111			"invalid Unicode escape", "unpaired high surrogate escape",
112			".rules[0].note", "string value",
113			"byte offset "+strconv.Itoa(escapeOffset), "line 1", "column ")
114		if got := data[escapeOffset]; got != '\\' {
115			t.Fatalf("reported offset %d must point at the escape backslash, got %q", escapeOffset, got)
116		}
117	}
