// --- 错误三分类不变：字符损坏 ≠ 不存在 ≠ 请求标识不合法 ---

func TestLoadReportCharacterErrorClassDistinct(t *testing.T) {
	dir := t.TempDir()
	r := oneRuleCharReport("反例：�重入")
	corruptID := writeVariantArchiveText(t, dir, r, func(doc string) string {
