58		hash := ArtifactHash(strictTestArtifact())
59		plain := strictDoc(
60			`"artifact":`+strictArtifactJSON,
61			`"rules":`+strictRulesJSON,
62			`"checks":[`+strictDefectCheck(hash, "", "")+`]`,
63		)
64		want := strictParsedReport(t, plain)
65	
66		for _, tc := range []struct {
67			name   string
68			prefix string
69			suffix string
70		}{
71			{"variant after formal field", "", `,"StAtus":"通过"`},
72			{"variant before formal field", `"StAtus":"通过",`, ""},
73		} {
74			t.Run(tc.name, func(t *testing.T) {
75				in := strictDoc(
76					`"artifact":`+strictArtifactJSON,
77					`"rules":`+strictRulesJSON,
78					`"checks":[`+strictDefectCheck(hash, tc.prefix, tc.suffix)+`]`,
79				)
80				got := strictParsedReport(t, in)
81	
82				// 正式缺陷仍生成该规则的缺陷。
83				if len(got.Findings) != 1 {
84					t.Fatalf("findings = %d, want 1 (formal 发现缺陷)", len(got.Findings))
85				}
86				f := got.Findings[0]
87				if f.RuleID != "r1" || f.Version != "1.0.0" || f.ArtifactHash != hash {
88					t.Fatalf("finding binding changed: %+v", f)
89				}
90				if f.Evidence != "counterexample: x" {
91					t.Fatalf("formal note evidence must be preserved, got %q", f.Evidence)
92				}
93				if got.Rules[0].Status != StatusDefect {
94					t.Fatalf("rule status = %q, want %q", got.Rules[0].Status, StatusDefect)
95				}
96				// 仅增加扩展信息不得改变报告标识、产物哈希与规则版本绑定。
97				if got.ReportID != want.ReportID {
98					t.Fatalf("extension member changed the report id:\n got %s\nwant %s", got.ReportID, want.ReportID)
99				}
100				if got.Artifact.Hash != hash {
101					t.Fatalf("artifact hash changed: %q", got.Artifact.Hash)
102				}
103			})
104		}
105	}
