	if checks[0].ArtifactHash != "abc" || checks[0].RuleID != "r1" || checks[0].Version != "1.0.0" ||
		checks[0].Status != StatusPass || checks[0].Note != "" {
		t.Errorf("check = %+v", checks[0])
	}
