250	// 的内容哈希，避免测试手写哈希。
251	func contractsentinelArtifactHashForCharset() string {
252		return contractsentinel.ArtifactHash(contractsentinel.Artifact{
253			Name: "Vault", ABI: "abi", Bytecode: "0x1", Source: "Vault.sol",
254		})
255	}
